#include <vector>
#include <cstddef>
std::size_t lower(const std::vector<int>& a, int x) {
  std::size_t l = 0, r = a.size();
  while (l < r) {
    auto m = l + (r - l) / 2;
    if (a[m] < x) l = m + 1;
    else r = m;
  }
  return l;
}

#include <vector>
int find(std::vector<int>& parent, int x) {
  while (parent[x] != x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}
